select p.id, array(select r.id from public.rooms r where r.project_id=p.id and r.code = any(array['R19'])), array['wall','base'], 'Quy định vận hành Marriott · Khu pantry / sơ chế thực phẩm (bếp)','Marriott operating standard · Food Service Pantries','Wall: Ceramic tile with skirting same material as floor. Note: Marriott to approve floor finish.','Tường: ốp gạch ceramic, len chân tường cùng vật liệu với sàn. Lưu ý: Marriott phải duyệt.','Marriott BOH Finishes Schedule (minimum)',35 from public.projects p where p.name='BOH Westin Kim Mã';
insert into public.project_rules(project_id,room_ids,elements,title_vn,title_en,body_en,body_vn,source,sort)
select p.id, array(select r.id from public.rooms r where r.project_id=p.id and r.code = any(array['R19'])), array['ceiling'], 'Quy định vận hành Marriott · Khu pantry / sơ chế thực phẩm (bếp)','Marriott operating standard · Food Service Pantries','Ceiling: A fire rated (to local codes) and accessible, washable, non-corroding (tile and support) with recessed lighting. Submit specifications to MII for approval. Note: Marriott to approve floor finish.','Trần: chống cháy (theo quy chuẩn địa phương), có thể mở để kiểm tra, rửa được, không ăn mòn (cả tấm và khung đỡ), đèn âm trần. Nộp thông số kỹ thuật cho MII (Marriott International) để duyệt. Lưu ý: Marriott phải duyệt.','Marriott BOH Finishes Schedule (minimum)',36 from public.projects p where p.name='BOH Westin Kim Mã';
